}
.notif-item {
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background 0.15s;
  border-bottom: 1px solid rgba(59, 130, 246, 0.06);
}
.notif-item:hover {
  background: rgba(59, 130, 246, 0.07);
}
.notif-item--unread {
  background: rgba(59, 130, 246, 0.05);
}
.notif-icon {
  font-size: 20px;
  min-width: 24px;
}
.notif-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 2px;
}
.notif-msg {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.notif-time {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
}
.dropdown-user-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}
.dropdown-user-info strong {
  font-size: 14px;
  color: var(--text-primary);
}
.dropdown-user-info span {
  font-size: 12px;
  color: var(--text-muted);
}
.role-tag {
  font-size: 11px;
  background: rgba(59, 130, 246, 0.15);
  color: var(--accent-light);
  border-radius: 6px;
  padding: 2px 8px;
  width: fit-content;
  font-weight: 600;
}
.dropdown-logout {
  width: 100%;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.25);
  border-radius: 8px;
  color: #fca5a5;
  font-size: 13px;
  cursor: pointer;
  padding: 8px 12px;
  text-align: left;
  transition: background 0.18s;
}
.dropdown-logout:hover {
  background: rgba(239, 68, 68, 0.2);
}
/* ══════════════════════════════════════════════════════
   page header
══════════════════════════════════════════════════════ */
.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.page-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.page-header-icon {
  font-size: 28px;
}
.page-header-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
}
.page-header-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 2px;
}
.page-header-actions {
  display: flex;
  gap: 10px;
}
/* ══════════════════════════════════════════════════════
   kpi cards
══════════════════════════════════════════════════════ */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 18px;
  margin-bottom: 28px;
}
.kpi-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px 20px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  backdrop-filter: blur(8px);
  transition: transform 0.2s, box-shadow 0.2s;
}
.kpi-card:hover {
  transform: translatey(-2px);
  box-shadow: var(--shadow-glow);
}
.kpi-icon {
  font-size: 32px;
}
.kpi-label {
  font-size: 12px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}
.kpi-value {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}
.kpi-trend {
  font-size: 12px;
  margin-top: 4px;
  font-weight: 600;
}
.trend--up {
  color: var(--success);
}
.trend--down {
  color: var(--error);
}
.trend--stable {
  color: var(--text-muted);
}
.kpi-card--blue {
  border-left: 3px solid var(--accent);
}
.kpi-card--green {
  border-left: 3px solid var(--success);
}
.kpi-card--orange {
  border-left: 3px solid var(--warning);
}
.kpi-card--red {
  border-left: 3px solid var(--error);
}
/* ══════════════════════════════════════════════════════
   badges
══════════════════════════════════════════════════════ */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.2px;
}
.badge--blue {
  background: rgba(59, 130, 246, 0.15);
  color: #60a5fa;
}
.badge--green {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
}
.badge--orange {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
}
.badge--red {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
}
.badge--purple {
  background: rgba(139, 92, 246, 0.15);
  color: #a78bfa;
}
.badge--gray {
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
}
/* ══════════════════════════════════════════════════════
   table
══════════════════════════════════════════════════════ */
.table-wrapper {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  overflow-x: auto;
  backdrop-filter: blur(8px);
}
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  background: rgba(8, 13, 26, 0.6);
  padding: 13px 16px;
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.th-sortable {
  cursor: pointer;
  user-select: none;
}
.th-sortable:hover {
  color: var(--accent-light);
}
.sort-icon {
  color: var(--accent-light);
}
.data-table td {
  padding: 13px 16px;
  font-size: 14px;
  color: var(--text-secondary);
  border-bottom: 1px solid rgba(59, 130, 246, 0.05);
}
.table-row:hover td {
  background: rgba(59, 130, 246, 0.04);
  color: var(--text-primary);
}
.table-loading,
.table-empty {
  text-align: center;
  padding: 40px;
  color: var(--text-muted);
}
.table-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-top: 1px solid var(--border);
}
.pagination-info {
  font-size: 12px;
  color: var(--text-muted);
}
.pagination-btns {
  display: flex;
  gap: 4px;
}
.pagination-btn {
  padding: 5px 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s;
}
.pagination-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--text-primary);
}
.pagination-btn--active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.pagination-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pagination-ellipsis {
  padding: 5px 4px;
  color: var(--text-muted);
  font-size: 13px;
}
/* ══════════════════════════════════════════════════════
   modal
══════════════════════════════════════════════════════ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 500;
  padding: 20px;
  backdrop-filter: blur(4px);
  animation: fadein 0.15s ease;
}
@keyframes fadein {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}
.modal-panel {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  animation: fadeslideup 0.2s ease both;
  overflow: hidden;
}
.modal-panel--sm {
  width: 100%;
  max-width: 380px;
}
.modal-panel--md {
  width: 100%;
  max-width: 560px;
}
.modal-panel--lg {
  width: 100%;
  max-width: 780px;
}
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 22px;
  border-bottom: 1px solid var(--border);
}
.modal-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}
.modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 16px;
  transition: color 0.15s;
  padding: 0;
}
.modal-close:hover {
  color: var(--text-primary);
}
.modal-body {
  padding: 22px;
}
/* ══════════════════════════════════════════════════════
   confirm dialog
══════════════════════════════════════════════════════ */
.confirm-message {
  color: var(--text-secondary);
  font-size: 14px;
  margin-bottom: 22px;
  line-height: 1.5;
}
.confirm-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}
.btn-secondary {
  padding: 9px 18px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.18s;
  font-family: 'inter', sans-serif;
}
.btn-secondary:hover {
  border-color: var(--border-hover);
  color: var(--text-primary);
}
.btn-danger {
  padding: 9px 18px;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.3);
  border-radius: var(--radius);
  color: #f87171;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s;
  font-family: 'inter', sans-serif;
}
.btn-danger:hover {
  background: rgba(239, 68, 68, 0.25);
}
.btn-primary-sm {
  padding: 9px 18px;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  font-family: 'inter', sans-serif;
}
.btn-icon {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 9px 18px;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  font-family: 'inter', sans-serif;
  transition: all 0.2s;
  box-shadow: 0 4px 14px rgba(59, 130, 246, 0.3);
}
.btn-icon:hover {
  transform: translatey(-1px);
  box-shadow: 0 6px 20px rgba(59, 130, 246, 0.45);
}
/* ══════════════════════════════════════════════════════
   search input
══════════════════════════════════════════════════════ */
.search-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}
.search-icon {
  position: absolute;
  left: 12px;
  font-size: 14px;
  color: var(--text-muted);
}
.search-input {
  padding: 9px 36px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: 'inter', sans-serif;
  outline: none;
  transition: all 0.2s;
  min-width: 240px;
}
.search-input:focus {
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.06);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.search-clear {
  position: absolute;
  right: 10px;
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 13px;
}
/* ══════════════════════════════════════════════════════
   empty state
══════════════════════════════════════════════════════ */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}
.empty-state-icon {
  font-size: 48px;
  margin-bottom: 16px;
  opacity: 0.7;
}
.empty-state-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-secondary);
}
.empty-state-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 6px;
}
/* ══════════════════════════════════════════════════════
   dashboard charts section
══════════════════════════════════════════════════════ */
.charts-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
  margin-bottom: 28px;
}
.dashboard-sections-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 20px;
}
.warehouse-quick-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.chart-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px;
  backdrop-filter: blur(8px);
}
.chart-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 18px;
}
/* ══════════════════════════════════════════════════════
   placeholder page
══════════════════════════════════════════════════════ */
.placeholder-page {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: calc(100vh - var(--topbar-h) - 56px);
  gap: 12px;
  color: var(--text-muted);
}
.placeholder-page span {
  font-size: 52px;
}
.placeholder-page h2 {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-primary);
}
.placeholder-page p {
  font-size: 14px;
}
/* ══════════════════════════════════════════════════════
   form elements (app-wide)
══════════════════════════════════════════════════════ */
.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.field-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}
.field-input,
.field-select,
.field-textarea {
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: 'inter', sans-serif;
  outline: none;
  transition: all 0.2s;
  width: 100%;
}
.field-input:focus,
.field-select:focus,
.field-textarea:focus {
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.06);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.field-select {
  appearance: none;
  cursor: pointer;
}
.field-select option {
  background: #0d1528;
}
.field-textarea {
  resize: vertical;
  min-height: 80px;
}
/* ══════════════════════════════════════════════════════
   responsive
══════════════════════════════════════════════════════ */
@media (max-width: 900px) {
  .app-shell {
    grid-template-columns: var(--sidebar-collapsed-w) 1fr;
  }

  .sidebar-logo-text,
  .sidebar-link-label,
  .sidebar-user-info {
    display: none;
  }

  .charts-grid,
  .dashboard-sections-grid,
  .warehouse-quick-actions {
    grid-template-columns: 1fr;
  }

  .kpi-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .app-content {
    padding: 16px;
  }

  .kpi-grid {
    grid-template-columns: 1fr;
  }

  .page-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .page-header-actions {
    width: 100%;
    display: flex;
    flex-wrap: wrap;
  }

  .page-header-actions>* {
    flex: 1 1 auto;
  }

  .search-input-wrapper,
  .search-input {
    width: 100%;
    min-width: 0;
  }

  .data-table th,
  .data-table td {
    padding: 10px 12px;
    font-size: 12px;
  }
