.btn-ghost:hover {
  color: #fff;
}
/* ─── divider ─── */
.auth-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 22px 0;
  color: var(--text-muted);
  font-size: 12px;
}
.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}
/* ─── link row ─── */
.auth-link-row {
  text-align: center;
  margin-top: 22px;
  font-size: 13px;
  color: var(--text-secondary);
}
/* ─── spinner ─── */
.spinner {
  width: 18px;
  height: 18px;
