  padding: 13px;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  letter-spacing: -0.2px;
  box-shadow: 0 4px 16px rgba(59, 130, 246, 0.3);
  margin-top: 8px;
}
.btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(59, 130, 246, 0.45);
}
.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}
.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.btn-ghost {
  background: none;
  border: none;
  color: var(--accent-light);
  font-size: 13px;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  text-decoration: underline;
  padding: 0;
  transition: color 0.2s;
}
.btn-ghost:hover {
  color: #fff;
}
/* ─── Divider ─── */
.auth-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 22px 0;
  color: var(--text-muted);
  font-size: 12px;
}
.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}
/* ─── Link Row ─── */
.auth-link-row {
  text-align: center;
  margin-top: 22px;
  font-size: 13px;
  color: var(--text-secondary);
}
/* ─── Spinner ─── */
.spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  display: inline-block;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
/* ─── Fade-in animation ─── */
@keyframes fadeSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.auth-card {
  animation: fadeSlideUp 0.45s ease both;
}
/* ─── Step indicator for forgot password ─── */
.steps {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 28px;
}
.step {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  transition: all 0.3s ease;
  border: 1px solid var(--border);
  color: var(--text-muted);
}
.step.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  box-shadow: 0 0 12px var(--accent-glow);
}
.step.done {
  background: var(--success);
  border-color: var(--success);
  color: #fff;
}
.step-line {
  flex: 1;
  height: 1px;
  background: var(--border);
  transition: background 0.3s;
}
.step-line.done {
  background: var(--success);
}
/* ─── Password strength bar ─── */
.password-strength {
  margin-top: 6px;
  display: flex;
  gap: 4px;
}
.strength-bar {
  height: 3px;
  flex: 1;
  border-radius: 2px;
  background: var(--text-muted);
  transition: background 0.3s;
}
.strength-bar.weak {
  background: var(--error);
}
.strength-bar.medium {
  background: var(--warning);
}
.strength-bar.strong {
  background: var(--success);
}
/* ─── Role badges ─── */
.role-description {
  margin-top: 6px;
  font-size: 11px;
  color: var(--text-muted);
  padding-left: 2px;
}
.mobile-brand-logo {
  display: none;
}
/* ─── Responsive ─── */
@media (max-width: 768px) {
  .auth-layout {
    grid-template-columns: 1fr;
  }

  .auth-panel-left {
    display: none;
  }

  .auth-panel-right {
    padding: 40px 24px;
  }

  .mobile-brand-logo {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 24px;
  }

  .mobile-brand-logo .brand-logo-icon {
    width: 42px;
    height: 42px;
    font-size: 20px;
    box-shadow: 0 4px 16px var(--accent-glow);
  }

  .mobile-brand-logo .brand-logo-text strong {
    font-size: 15px;
  }

  .mobile-brand-logo .brand-logo-text span {
    font-size: 11px;
  }
}
/* ══════════════════════════════════════════════════════
   APP SHELL — main layout
══════════════════════════════════════════════════════ */
:root {
  --sidebar-w: 240px;
  --sidebar-collapsed-w: 68px;
  --topbar-h: 60px;
}
.app-shell {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr;
  min-height: 100vh;
  transition: grid-template-columns 0.25s ease;
}
.app-shell--collapsed {
  grid-template-columns: var(--sidebar-collapsed-w) 1fr;
}
.app-main {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  overflow: hidden;
}
.app-content {
  flex: 1;
  padding: 28px 32px;
  overflow-y: auto;
}
/* ══════════════════════════════════════════════════════
   SIDEBAR
══════════════════════════════════════════════════════ */
.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  background: rgba(8, 13, 26, 0.98);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 20px 12px;
  gap: 4px;
  overflow: hidden;
  transition: width 0.25s ease;
  z-index: 100;
}
.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 8px 20px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 12px;
  overflow: hidden;
  white-space: nowrap;
}
.sidebar-logo-icon {
  width: 38px;
  height: 38px;
  min-width: 38px;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  box-shadow: 0 4px 14px var(--accent-glow);
}
.sidebar-logo-text strong {
  display: block;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}
.sidebar-logo-text span {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.sidebar-nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.sidebar-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 10px;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.18s ease;
  white-space: nowrap;
  overflow: hidden;
  position: relative;
}
.sidebar-link:hover {
  background: rgba(59, 130, 246, 0.1);
  color: var(--text-primary);
}
.sidebar-link--active {
  background: rgba(59, 130, 246, 0.15);
  color: var(--accent-light);
  font-weight: 600;
}
.sidebar-link-icon {
  font-size: 18px;
  min-width: 22px;
  text-align: center;
}
.sidebar-link-indicator {
  position: absolute;
  right: 10px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}
.sidebar-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border-top: 1px solid var(--border);
  margin-top: 8px;
  overflow: hidden;
  white-space: nowrap;
}
.sidebar-user-avatar {
  width: 34px;
  height: 34px;
  min-width: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
}
.sidebar-user-name {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}
.sidebar-user-role {
  font-size: 11px;
  color: var(--text-muted);
}
.sidebar-toggle {
  align-self: flex-end;
  background: none;
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 12px;
  padding: 5px 8px;
  margin-top: 8px;
  transition: all 0.18s;
}
.sidebar-toggle:hover {
  color: var(--accent-light);
  border-color: var(--accent);
}
/* ══════════════════════════════════════════════════════
   TOPBAR
══════════════════════════════════════════════════════ */
.topbar {
  height: var(--topbar-h);
  background: rgba(8, 13, 26, 0.95);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 28px;
  position: sticky;
  top: 0;
  z-index: 90;
  backdrop-filter: blur(12px);
}
.topbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.topbar-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}
.topbar-right {
  display: flex;
  align-items: center;
  gap: 10px;
}
.topbar-icon-btn {
  position: relative;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 18px;
  padding: 7px 10px;
  transition: all 0.18s;
}
.topbar-icon-btn:hover {
  border-color: var(--accent);
  color: var(--text-primary);
}
.badge-count {
  position: absolute;
  top: -4px;
  right: -4px;
  background: var(--error);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  border-radius: 10px;
  padding: 1px 5px;
  min-width: 18px;
  text-align: center;
}
.topbar-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border: none;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: box-shadow 0.18s;
}
.topbar-avatar:hover {
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.topbar-dropdown {
  position: relative;
}
/* WebSocket indicator */
.ws-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text-muted);
}
.ws-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}
.ws-indicator--on .ws-dot {
  background: var(--success);
  box-shadow: 0 0 6px var(--success);
}
.ws-indicator--off .ws-dot {
  background: var(--error);
}
/* ══════════════════════════════════════════════════════
   DROPDOWNS
══════════════════════════════════════════════════════ */
.dropdown-panel {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  z-index: 200;
  animation: fadeSlideUp 0.2s ease both;
}
.dropdown-panel--notifs {
  width: 340px;
}
.dropdown-panel--user {
  width: 220px;
  padding: 12px;
}
.dropdown-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
}
.dropdown-action {
  background: none;
  border: none;
  color: var(--accent-light);
  font-size: 11px;
  cursor: pointer;
  padding: 0;
}
.dropdown-action:hover {
  color: #fff;
}
.dropdown-empty {
  padding: 24px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
}
.notif-list {
  max-height: 320px;
  overflow-y: auto;
}
.notif-item {
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background 0.15s;
  border-bottom: 1px solid rgba(59, 130, 246, 0.06);
}
.notif-item:hover {
  background: rgba(59, 130, 246, 0.07);
}
.notif-item--unread {
  background: rgba(59, 130, 246, 0.05);
}
.notif-icon {
  font-size: 20px;
  min-width: 24px;
}
.notif-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 2px;
}
.notif-msg {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.notif-time {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
}
.dropdown-user-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}
.dropdown-user-info strong {
  font-size: 14px;
  color: var(--text-primary);
}
.dropdown-user-info span {
  font-size: 12px;
  color: var(--text-muted);
}
.role-tag {
  font-size: 11px;
  background: rgba(59, 130, 246, 0.15);
  color: var(--accent-light);
  border-radius: 6px;
  padding: 2px 8px;
  width: fit-content;
  font-weight: 600;
}
.dropdown-logout {
  width: 100%;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.25);
  border-radius: 8px;
  color: #fca5a5;
  font-size: 13px;
  cursor: pointer;
  padding: 8px 12px;
  text-align: left;
  transition: background 0.18s;
}
.dropdown-logout:hover {
  background: rgba(239, 68, 68, 0.2);
}
/* ══════════════════════════════════════════════════════
   PAGE HEADER
══════════════════════════════════════════════════════ */
.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.page-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.page-header-icon {
  font-size: 28px;
}
.page-header-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
}
.page-header-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 2px;
}
.page-header-actions {
  display: flex;
  gap: 10px;
}
/* ══════════════════════════════════════════════════════
   KPI CARDS
══════════════════════════════════════════════════════ */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 18px;
  margin-bottom: 28px;
}
.kpi-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px 20px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  backdrop-filter: blur(8px);
  transition: transform 0.2s, box-shadow 0.2s;
}
.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
}
.kpi-icon {
  font-size: 32px;
}
.kpi-label {
  font-size: 12px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}
.kpi-value {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}
.kpi-trend {
  font-size: 12px;
  margin-top: 4px;
  font-weight: 600;
}
.trend--up {
  color: var(--success);
}
.trend--down {
  color: var(--error);
}
.trend--stable {
  color: var(--text-muted);
}
.kpi-card--blue {
  border-left: 3px solid var(--accent);
}
.kpi-card--green {
  border-left: 3px solid var(--success);
}
.kpi-card--orange {
  border-left: 3px solid var(--warning);
}
.kpi-card--red {
  border-left: 3px solid var(--error);
}
/* ══════════════════════════════════════════════════════
   BADGES
══════════════════════════════════════════════════════ */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.2px;
}
.badge--blue {
  background: rgba(59, 130, 246, 0.15);
  color: #60a5fa;
}
.badge--green {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
}
.badge--orange {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
}
.badge--red {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
}
.badge--purple {
  background: rgba(139, 92, 246, 0.15);
  color: #a78bfa;
}
.badge--gray {
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
}
/* ══════════════════════════════════════════════════════
   TABLE
══════════════════════════════════════════════════════ */
.table-wrapper {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  overflow-x: auto;
  backdrop-filter: blur(8px);
}
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  background: rgba(8, 13, 26, 0.6);
  padding: 13px 16px;
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.th-sortable {
  cursor: pointer;
  user-select: none;
}
.th-sortable:hover {
  color: var(--accent-light);
}
.sort-icon {
  color: var(--accent-light);
}
.data-table td {
  padding: 13px 16px;
  font-size: 14px;
  color: var(--text-secondary);
  border-bottom: 1px solid rgba(59, 130, 246, 0.05);
}
.table-row:hover td {
  background: rgba(59, 130, 246, 0.04);
  color: var(--text-primary);
}
.table-loading,
.table-empty {
  text-align: center;
  padding: 40px;
  color: var(--text-muted);
}
.table-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-top: 1px solid var(--border);
}
.pagination-info {
  font-size: 12px;
  color: var(--text-muted);
}
.pagination-btns {
  display: flex;
  gap: 4px;
}
.pagination-btn {
  padding: 5px 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s;
}
.pagination-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--text-primary);
}
.pagination-btn--active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.pagination-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pagination-ellipsis {
  padding: 5px 4px;
  color: var(--text-muted);
  font-size: 13px;
}
/* ══════════════════════════════════════════════════════
   MODAL
══════════════════════════════════════════════════════ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 500;
  padding: 20px;
  backdrop-filter: blur(4px);
  animation: fadeIn 0.15s ease;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}
.modal-panel {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  animation: fadeSlideUp 0.2s ease both;
  overflow: hidden;
}
.modal-panel--sm {
  width: 100%;
  max-width: 380px;
}
.modal-panel--md {
  width: 100%;
  max-width: 560px;
}
.modal-panel--lg {
  width: 100%;
  max-width: 780px;
}
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 22px;
  border-bottom: 1px solid var(--border);
}
.modal-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}
.modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 16px;
  transition: color 0.15s;
  padding: 0;
}
.modal-close:hover {
  color: var(--text-primary);
}
.modal-body {
  padding: 22px;
}
/* ══════════════════════════════════════════════════════
   CONFIRM DIALOG
══════════════════════════════════════════════════════ */
.confirm-message {
  color: var(--text-secondary);
  font-size: 14px;
  margin-bottom: 22px;
  line-height: 1.5;
}
.confirm-actions {
  display: flex;
