/* ─── Google Font ─── */
/* ─── CSS Custom Properties ─── */
:root {
  --bg-primary: #080d1a;
  --bg-secondary: #0d1528;
  --bg-card: rgba(13, 21, 40, 0.85);
  --accent: #3b82f6;
  --accent-light: #60a5fa;
  --accent-dark: #1d4ed8;
  --accent-glow: rgba(59, 130, 246, 0.35);
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --text-muted: #475569;
  --border: rgba(59, 130, 246, 0.18);
  --border-hover: rgba(59, 130, 246, 0.45);
  --success: #10b981;
  --error: #ef4444;
  --warning: #f59e0b;
  --radius: 12px;
  --radius-lg: 18px;
  --shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
