  color: var(--text-secondary);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}
.brand-headline {
  position: relative;
  z-index: 1;
  margin-bottom: 28px;
}
.brand-headline h1 {
  font-size: 38px;
