.deco-boxes {
  position: absolute;
  bottom: 60px;
  right: -30px;
  z-index: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  opacity: 0.35;
}
/* ─── Right Panel (Form) ─── */
.auth-panel-right {
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 40px;
  overflow-y: auto;
}
.auth-card {
  width: 100%;
  max-width: 420px;
}
.auth-card-header {
  margin-bottom: 32px;
  text-align: left;
}
