  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}
.empty-state-icon {
  font-size: 48px;
  margin-bottom: 16px;
  opacity: 0.7;
}
.empty-state-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-secondary);
}
.empty-state-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 6px;
}
/* ══════════════════════════════════════════════════════
   DASHBOARD CHARTS SECTION
══════════════════════════════════════════════════════ */
.charts-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
  margin-bottom: 28px;
}
.dashboard-sections-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 20px;
}
.warehouse-quick-actions {
  display: grid;
