}
.placeholder-page h2 {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-primary);
}
.placeholder-page p {
  font-size: 14px;
}
/* ══════════════════════════════════════════════════════
   FORM ELEMENTS (app-wide)
══════════════════════════════════════════════════════ */
.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.field-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}
.field-input,
.field-select,
.field-textarea {
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: 'Inter', sans-serif;
  outline: none;
  transition: all 0.2s;
  width: 100%;
}
.field-input:focus,
.field-select:focus,
.field-textarea:focus {
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.06);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.field-select {
  appearance: none;
  cursor: pointer;
}
.field-select option {
  background: #0d1528;
}
.field-textarea {
  resize: vertical;
  min-height: 80px;
}
/* ══════════════════════════════════════════════════════
   RESPONSIVE
══════════════════════════════════════════════════════ */
@media (max-width: 900px) {
  .app-shell {
    grid-template-columns: var(--sidebar-collapsed-w) 1fr;
