  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: 'Inter', sans-serif;
  outline: none;
  transition: all 0.2s ease;
}
.form-input::placeholder {
  color: var(--text-muted);
}
.form-input:focus {
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.06);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.form-input:focus~.input-icon,
.input-wrapper:focus-within .input-icon {
  color: var(--accent-light);
}
.form-input.no-icon {
  padding-left: 14px;
}
.input-action {
  position: absolute;
  right: 12px;
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 15px;
  transition: color 0.2s;
  padding: 0;
  display: flex;
  align-items: center;
}
.input-action:hover {
  color: var(--accent-light);
}
/* Select styling */
.form-select {
  width: 100%;
  padding: 12px 14px 12px 42px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: 'Inter', sans-serif;
  outline: none;
  transition: all 0.2s ease;
  appearance: none;
  cursor: pointer;
}
.form-select:focus {
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.06);
  box-shadow: 0 0 0 3px var(--accent-glow);
}
.form-select option {
  background: #0d1528;
  color: var(--text-primary);
}
/* ─── Alert / Error message ─── */
.alert {
  padding: 11px 14px;
  border-radius: var(--radius);
  font-size: 13px;
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.alert-error {
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #fca5a5;
}
.alert-success {
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: #6ee7b7;
}
/* ─── Buttons ─── */
.btn-primary {
  width: 100%;
  padding: 13px;
  background: linear-gradient(135deg, var(--accent), var(--accent-dark));
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  letter-spacing: -0.2px;
  box-shadow: 0 4px 16px rgba(59, 130, 246, 0.3);
  margin-top: 8px;
}
.btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(59, 130, 246, 0.45);
}
.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}
.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.btn-ghost {
  background: none;
  border: none;
  color: var(--accent-light);
  font-size: 13px;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  text-decoration: underline;
  padding: 0;
  transition: color 0.2s;
}
.btn-ghost:hover {
  color: #fff;
}
/* ─── Divider ─── */
.auth-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 22px 0;
  color: var(--text-muted);
  font-size: 12px;
}
.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}
/* ─── Link Row ─── */
.auth-link-row {
  text-align: center;
  margin-top: 22px;
  font-size: 13px;
  color: var(--text-secondary);
}
/* ─── Spinner ─── */
.spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  display: inline-block;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
/* ─── Fade-in animation ─── */
@keyframes fadeSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.auth-card {
  animation: fadeSlideUp 0.45s ease both;
}
/* ─── Step indicator for forgot password ─── */
.steps {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 28px;
}
.step {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  transition: all 0.3s ease;
